	@Test
	void patternCursorFillPreservesPositiveNoRangeFixedContextBatches() throws IOException {
		int physicalRows = 2_500;
		int firstContextRows = 1_000;
		CountingSweepSource source = new CountingSweepSource(true, true, false,
				rejectedQuadsAcrossContexts(physicalRows, firstContextRows));
		RowState row = row(source);
		PatternPlan pattern = new PatternPlan(Term.slot(KEY_SLOT), Term.constant(91L), Term.unbound(), Term.unbound(),
				new ContextConstraint(new long[] { 1L, 2L }), false, null, "spoc", null, physicalRows);
		PatternCursor cursor = pattern.openRaw(row, null);
		long[] buffer = new long[4_096 * 4];
		List<Integer> batches = new ArrayList<>();
		List<Long> subjects = new ArrayList<>();
		List<Long> contexts = new ArrayList<>();
		try {
			int rows;
			while ((rows = cursor.fill(buffer, 4_096)) > 0) {
				batches.add(rows);
				for (int i = 0; i < rows; i++) {
					subjects.add(buffer[i * 4]);
					contexts.add(buffer[i * 4 + 3]);
				}
			}
		} finally {
			try {
				cursor.close();
			} finally {
				row.memoryScope.close();
			}
		}

		List<Long> expectedSubjects = new ArrayList<>(physicalRows);
		List<Long> expectedContexts = new ArrayList<>(physicalRows);
		for (int i = 0; i < physicalRows; i++) {
			expectedSubjects.add(1_000L + i);
			expectedContexts.add(i < firstContextRows ? 1L : 2L);
		}
		assertAll("no-range fills preserve partial batches across fixed contexts",
				() -> assertEquals(firstContextRows, batches.get(0),
						"the first context returns a positive partial batch"),
				() -> assertTrue(batches.stream().allMatch(batch -> batch > 0), "partial batches remain positive"),
				() -> assertEquals(physicalRows,
						batches.stream().mapToInt(Integer::intValue).sum(),
						"all context rows are returned exactly once"),
				() -> assertEquals(expectedSubjects, subjects, "subject encounter order is preserved"),
				() -> assertEquals(expectedContexts, contexts, "context order is preserved across batches"),
				() -> assertEquals(physicalRows, source.ordinaryRawRows),
				() -> assertEquals(source.opens, source.closes, "every fixed-context iterator closes"));
	}

