	@Test
	void nextOnlyThenWeightedClaimsOnlyTheRemainingCopies() throws IOException {
		LmdbQueryMemoryManager previous = LmdbNativeHashJoin.queryMemoryOverride;
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(65_536L, 65_536L);
		LmdbNativeHashJoin.queryMemoryOverride = manager;
		RowState row = row(new NativeCancellationToken());
		LmdbQueryMemoryManager.QueryLedger ledger = row.memoryScope.ledger(manager);
		long baseline = ledger.usedBytes();
		WeightedPlan left = new WeightedPlan(row, KEY_SLOT, KEY_ID, 1L, null);
		FlattenedWeightedPlan right = new FlattenedWeightedPlan(VALUE_SLOT,
				new long[] { VALUE_ID, VALUE_ID + 1 }, new long[] { 3L, 2L });
		RowCursor cursor = new NativeAliasJoinMemoPlan(new JoinPlan(left, right)).open(row);

		try {
			assertTrue(cursor.next());
			assertEquals(VALUE_ID, row.slots[VALUE_SLOT]);
			assertTrue(cursor.next(), "unclaimed logical rows remain visible to ordinary next calls");
			assertEquals(VALUE_ID, row.slots[VALUE_SLOT], "the first next-only row repeats before the next value");
			FactorizedRowCursor weighted = (FactorizedRowCursor) cursor;
			assertEquals(2L, weighted.multiplicity(), "the weight claim covers only the remaining A copies");
			assertEquals(1L, weighted.multiplicity(), "a second getter sees one remaining current row");
			assertTrue(cursor.next());
			assertEquals(VALUE_ID + 1, row.slots[VALUE_SLOT]);
			assertTrue(cursor.next(), "the unclaimed B copy remains visible");
			assertEquals(VALUE_ID + 1, row.slots[VALUE_SLOT]);
			assertEquals(1L, weighted.multiplicity(), "the B weight excludes its already-emitted logical copy");
			assertEquals(1L, weighted.multiplicity());
			assertFalse(cursor.next());
		} finally {
			try {
				cursor.close();
				assertEquals(baseline, ledger.usedBytes(), "mixed weighted and plain consumption releases memory");
			} finally {
				row.memoryScope.close();
				LmdbNativeHashJoin.queryMemoryOverride = previous;
			}
		}
	}

	@Test
	void realSourceMemoPreservesEmptyAndDuplicateCorrelationsWhenEntriesCannotBeAdmitted() throws Exception {
		String queryText = "SELECT ?source ?value WHERE { ?source ?rarePredicate ?gate . "
				+ "FILTER(?gate = \"admit\") BIND(?source AS ?focus) "
				+ "?focus <urn:predicate:facet> ?value . FILTER(STR(?value) = \"keep\") }";
		SailRepository nativeRepository = repository(directory.resolve("native"), true);
		SailRepository genericRepository = repository(directory.resolve("generic"), false);
		try {
			loadMemoAdmissionFixture(nativeRepository);
			loadMemoAdmissionFixture(genericRepository);

			Map<String, Integer> expected = queryBag(genericRepository, queryText);
			Map<String, Integer> expectedBag = Map.of("urn:subject:shared|keep", 10);
			assertEquals(expectedBag, expected,
					"the real fixture includes repeated correlated keys, an empty fragment, and duplicate projected rows");

			LmdbQueryMemoryManager roomyManager = LmdbQueryMemoryManager.createForTesting(1L << 20, 1L << 20);
			QueryMeasurement roomy = runNativeQuery(nativeRepository, queryText, roomyManager);
			LmdbQueryMemoryManager limitedManager = LmdbQueryMemoryManager.createForTesting(520L, 520L);
			QueryMeasurement limited = runNativeQuery(nativeRepository, queryText, limitedManager);

			assertEquals(expected, roomy.bag(), "admitted memo fragments preserve the exact LMDB source bag");
			assertEquals(expected, limited.bag(), "denied fragment admission falls back without changing the LMDB bag");
			assertTrue(roomy.scannedRows() > 0, "the admitted query reports real LMDB source work");
			assertTrue(limited.scannedRows() > roomy.scannedRows(),
					() -> "denied per-key fragments must reopen their real source; roomy=" + roomy.scannedRows()
							+ ", limited=" + limited.scannedRows() + "\nroomy telemetry:\n" + roomy.telemetry()
							+ "\nlimited telemetry:\n" + limited.telemetry());
			assertEquals(520L, limited.peakBytes(),
					"the memo owner fits exactly while its per-key fragment entry is refused");
			assertTrue(roomy.peakBytes() > limited.peakBytes(),
					"the roomy run admits and retains a fragment during capture");
			assertEquals(0L, roomy.retainedBytes(),
					"closing the admitted query releases its memo and source ownership");
			assertEquals(0L, limited.retainedBytes(), "closing after refused admissions releases its query ownership");
			assertTrue(roomy.telemetry().startsWith("LMDB native physical plan (executed)"));
			assertTrue(limited.telemetry().startsWith("LMDB native physical plan (executed)"));
			assertTrue(roomy.telemetry().contains("nativeExecutionPath=nestedLoop"));
			assertTrue(limited.telemetry().contains("nativeExecutionPath=nestedLoop"));
			assertEquals(2L, facetSourceOpens(roomy.telemetry()),
					"the completed nonempty and empty correlations are each captured once");
			assertEquals(7L, facetSourceOpens(limited.telemetry()),
					"refusing entry reservations reopens the facet source for all seven left rows");

			String keyFrameQuery = "SELECT ?source ?value WHERE { ?source ?rarePredicate ?gate . "
					+ "FILTER(?gate = \"admit\") ?source <urn:predicate:choice> ?wanted . "
					+ "BIND(?source AS ?focus) ?focus <urn:predicate:facet> ?value . FILTER(?value = ?wanted) }";
			Map<String, Integer> expectedKeyFrameBag = Map.of(
					"urn:subject:shared|urn:value:red", 5,
					"urn:subject:shared|urn:value:blue", 5);
			assertEquals(expectedKeyFrameBag, queryBag(genericRepository, keyFrameQuery),
					"the independent evaluator confirms two left frames share one alias but differ on ?wanted");
			LmdbQueryMemoryManager keyFrameManager = LmdbQueryMemoryManager.createForTesting(1L << 20, 1L << 20);
			QueryMeasurement keyFrame = runNativeQuery(nativeRepository, keyFrameQuery, keyFrameManager);
			Path keyFrameDiagnostic = Files.createDirectories(
					Path.of("target", "alias-join-memo-memory-lifecycle-20261027", "key-frame-correlations"));
			Files.writeString(keyFrameDiagnostic.resolve("pre-assert-measurement.txt"),
					"query:\n" + keyFrameQuery + "\nexpectedBag=" + expectedKeyFrameBag + "\nactualBag="
							+ keyFrame.bag() + "\nfacetSourceOpens=" + facetSourceOpens(keyFrame.telemetry())
							+ "\nretainedBytes=" + keyFrame.retainedBytes() + "\n\ntelemetry:\n"
							+ keyFrame.telemetry());
			assertEquals(expectedKeyFrameBag, keyFrame.bag(),
					"memo keys must include each changing right-fragment read, not only the aliased subject");
			assertEquals(2L, facetSourceOpens(keyFrame.telemetry()),
					"the shared subject's red and blue frames need separate complete captures");
			assertEquals(0L, keyFrame.retainedBytes(), "closing the correlated query releases both frame entries");

			Map<String, Value> redBinding = Map.of("wanted",
					nativeRepository.getValueFactory().createIRI("urn:value:red"));
			Map<String, Value> blueBinding = Map.of("wanted",
					nativeRepository.getValueFactory().createIRI("urn:value:blue"));
			Map<String, Integer> expectedRedBag = Map.of("urn:subject:shared|urn:value:red", 5);
			Map<String, Integer> expectedBlueBag = Map.of("urn:subject:shared|urn:value:blue", 5);
			assertEquals(expectedRedBag, queryBag(genericRepository, keyFrameQuery, redBinding));
			QueryMeasurement redInvocation = runNativeQuery(nativeRepository, keyFrameQuery, keyFrameManager,
					redBinding);
			assertEquals(expectedRedBag, redInvocation.bag(),
					"an incoming binding produces an independent red-only query invocation");
			assertEquals(1L, facetSourceOpens(redInvocation.telemetry()));
			assertEquals(0L, redInvocation.retainedBytes(), "the red invocation releases its query-local memo");
			assertEquals(expectedBlueBag, queryBag(genericRepository, keyFrameQuery, blueBinding));
			QueryMeasurement blueInvocation = runNativeQuery(nativeRepository, keyFrameQuery, keyFrameManager,
					blueBinding);
			assertEquals(expectedBlueBag, blueInvocation.bag(),
					"a later blue invocation must not reuse the prior red invocation's fragment");
			assertEquals(1L, facetSourceOpens(blueInvocation.telemetry()));
			assertEquals(0L, blueInvocation.retainedBytes(), "the blue invocation releases its query-local memo");

			Path evidence = Files.createDirectories(Path.of("target", "alias-join-memo-memory", "entry-admission"));
			Files.writeString(evidence.resolve("measurement.txt"),
					"query:\n" + queryText + "\nexpectedBag=" + expected + "\nroomyBag=" + roomy.bag()
							+ "\nlimitedBag=" + limited.bag() + "\nroomyScannedRows=" + roomy.scannedRows()
							+ "\nlimitedScannedRows=" + limited.scannedRows() + "\nroomyPeakBytes=" + roomy.peakBytes()
							+ "\nlimitedPeakBytes=" + limited.peakBytes() + "\nroomyRetainedBytes="
							+ roomy.retainedBytes() + "\nlimitedRetainedBytes=" + limited.retainedBytes()
							+ "\nroomyFacetSourceOpens=" + facetSourceOpens(roomy.telemetry())
							+ "\nlimitedFacetSourceOpens=" + facetSourceOpens(limited.telemetry())
							+ "\n\nroomy telemetry:\n" + roomy.telemetry() + "\n\nlimited telemetry:\n"
							+ limited.telemetry());
			Path keyFrameEvidence = Files.createDirectories(
					Path.of("target", "alias-join-memo-memory-lifecycle-20261027", "key-frame-correlations"));
			Files.writeString(keyFrameEvidence.resolve("measurement.txt"),
					"query:\n" + keyFrameQuery + "\nexpectedBag=" + expectedKeyFrameBag + "\nactualBag="
							+ keyFrame.bag() + "\nfacetSourceOpens=" + facetSourceOpens(keyFrame.telemetry())
							+ "\nredBindingBag=" + redInvocation.bag() + "\nredBindingSourceOpens="
							+ facetSourceOpens(redInvocation.telemetry()) + "\nblueBindingBag=" + blueInvocation.bag()
							+ "\nblueBindingSourceOpens=" + facetSourceOpens(blueInvocation.telemetry())
							+ "\n\nkey-frame telemetry:\n" + keyFrame.telemetry()
							+ "\n\nred invocation telemetry:\n" + redInvocation.telemetry()
							+ "\n\nblue invocation telemetry:\n" + blueInvocation.telemetry());
		} finally {
			nativeRepository.shutDown();
			genericRepository.shutDown();
		}
	}

	@Test
	void partiallyConsumedFragmentIsDiscardedBeforeTheNextExecution() throws IOException {
		LmdbQueryMemoryManager previous = LmdbNativeHashJoin.queryMemoryOverride;
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(65_536L, 65_536L);
		LmdbNativeHashJoin.queryMemoryOverride = manager;
		RowState row = row(new NativeCancellationToken());
		LmdbQueryMemoryManager.QueryLedger ledger = row.memoryScope.ledger(manager);
		long baseline = ledger.usedBytes();
		WeightedPlan left = new WeightedPlan(row, KEY_SLOT, KEY_ID, 1L, null);
		WeightedPlan right = new WeightedPlan(row, VALUE_SLOT,
				new long[] { VALUE_ID, VALUE_ID + 1, VALUE_ID + 2 }, new long[] { 1L, 1L, 1L }, null);
		SlotPlan memo = new NativeAliasJoinMemoPlan(new JoinPlan(left, right));
		RowCursor partial = memo.open(row);
		try {
			assertTrue(partial.next(), "the first row starts an incomplete right-fragment capture");
			assertEquals(VALUE_ID, row.slots[VALUE_SLOT]);
			assertTrue(ledger.usedBytes() > baseline, "the pending capture reserves query memory before completion");
		} finally {
			partial.close();
		}
		assertEquals(baseline, ledger.usedBytes(), "early close discards pending data and returns to baseline");

		RowCursor reopened = memo.open(row);
		List<Long> reopenedValues = new ArrayList<>();
		try {
			while (reopened.next()) {
				reopenedValues.add(row.slots[VALUE_SLOT]);
			}
		} finally {
			reopened.close();
		}
		assertEquals(List.of(VALUE_ID, VALUE_ID + 1, VALUE_ID + 2), reopenedValues,
				"a new execution reads the complete source fragment instead of a partial cached prefix");
		assertEquals(2, right.opens, "the partial and reopened executions each open the real plan cursor");
		assertEquals(baseline, ledger.usedBytes(), "the reopened execution closes all memo reservations");
		assertEquals(0L, manager.usedBytes(), "no reservation survives either execution");
		try {
			Path evidence = Files.createDirectories(
					Path.of("target", "alias-join-memo-memory-lifecycle-20261027", "early-close-reopen"));
			Files.writeString(evidence.resolve("measurement.txt"),
					"firstExecutionRows=1 (closed before fragment exhaustion)\nreopenedBag=" + reopenedValues
							+ "\nrightPlanOpens=" + right.opens + "\nledgerBaseline=" + baseline
							+ "\nledgerAfterBothExecutions=" + ledger.usedBytes());
		} finally {
			row.memoryScope.close();
			LmdbNativeHashJoin.queryMemoryOverride = previous;
		}
	}

	@Test
	void planRowsExpandUnweightedBagsAndPreserveWeightedCounts() {
		int multiplicity = 5;
		PlanRowsBagPlan ordinaryPlan = new PlanRowsBagPlan(VALUE_ID, multiplicity);
		LmdbNativeKernelIr.Kernel rowShape = new LmdbNativeKernelIr.Kernel(1,
				List.of(new LmdbNativeKernelIr.PlanRows(0, new int[] { 0 })),
				new LmdbNativeKernelIr.Emit(new int[] { 0 }, false, LmdbNativeKernelIr.OutputMods.none()));
		JaninoKernel rowKernel = LmdbNativeKernelInterpreter.forRows(rowShape);
		try {
			rowKernel.bind(planContext(ordinaryPlan));
			long[] buffer = new long[multiplicity];
			List<Long> actual = new ArrayList<>();
			int count;
			while ((count = rowKernel.fill(buffer, multiplicity)) > 0) {
				for (int i = 0; i < count; i++) {
					actual.add(buffer[i]);
				}
			}
			assertEquals(List.of(VALUE_ID, VALUE_ID, VALUE_ID, VALUE_ID, VALUE_ID), actual,
					"ordinary PlanRows evaluation must expand the bag multiplicity");
			assertTrue(ordinaryPlan.unweightedFillCalls > 0, "row emission must call Cursor.fill");
			assertEquals(0, ordinaryPlan.weightedFillCalls, "row emission must not silently bypass per-row semantics");
		} finally {
			rowKernel.close();
			ordinaryPlan.close();
		}

		PlanRowsBagPlan weightedPlan = new PlanRowsBagPlan(VALUE_ID, multiplicity);
		LmdbNativeKernelIr.Kernel countShape = new LmdbNativeKernelIr.Kernel(1,
				List.of(new LmdbNativeKernelIr.PlanRows(0, new int[] { 0 })),
				new LmdbNativeKernelIr.Aggregate(new int[0],
						new LmdbNativeKernelIr.AggregateOutput[] { LmdbNativeKernelIr.AggregateOutput.countStar() },
						null,
						LmdbNativeKernelIr.OutputMods.none()));
		JaninoKernel countKernel = LmdbNativeKernelInterpreter.forAggregate(countShape);
		try {
			countKernel.bind(planContext(weightedPlan));
			long[] result = new long[1];
			assertEquals(1, countKernel.fill(result, 1), "COUNT(*) emits one scalar result");
			assertEquals(multiplicity, result[0], "weighted PlanRows must retain the exact bag count");
			assertTrue(weightedPlan.weightedFillCalls > 0, "COUNT(*) must consume Cursor.fillWeighted");
			assertEquals(0, weightedPlan.unweightedFillCalls, "weighted COUNT(*) must avoid expanding physical rows");
		} finally {
			countKernel.close();
			weightedPlan.close();
		}
	}

	@Test
	void boundPlanRowsExpandAndWeightTheRealProducerAcrossPartialWindowsAndClose() throws Exception {
		LmdbQueryMemoryManager previous = LmdbNativeHashJoin.queryMemoryOverride;
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(1L << 20, 1L << 20);
		LmdbNativeHashJoin.queryMemoryOverride = manager;
		try {
			RowState plainRow = row(new NativeCancellationToken());
			LmdbQueryMemoryManager.QueryLedger plainLedger = plainRow.memoryScope.ledger(manager);
			long plainBaseline = plainLedger.usedBytes();
			WeightedPlan plainPlan = new WeightedPlan(plainRow, VALUE_SLOT,
					new long[] { VALUE_ID, VALUE_ID + 1 }, new long[] { 3L, 5L }, null);
			LmdbNativeKernelIr.Kernel rowShape = new LmdbNativeKernelIr.Kernel(1,
					List.of(new LmdbNativeKernelIr.PlanRows(0, new int[] { 0 })),
					new LmdbNativeKernelIr.Emit(new int[] { 0 }, false, LmdbNativeKernelIr.OutputMods.none()));
			Path rowDirectory = Files.createTempDirectory("bound-plan-rows-");
			KernelContext rowContext = boundPlanContext(plainRow, plainPlan);
			JaninoKernel rowKernel = GeneratedBorrowedFtreeContractTest.compile(rowShape.className(),
					LmdbNativeKernelEmitter.emit(rowShape), rowDirectory);
			try {
				rowKernel.bind(rowContext);
				long[] buffer = new long[3];
				List<Long> actual = new ArrayList<>();
				int count;
				while ((count = rowKernel.fill(buffer, buffer.length)) > 0) {
					for (int i = 0; i < count; i++) {
						actual.add(buffer[i]);
					}
				}
				assertEquals(List.of(VALUE_ID, VALUE_ID, VALUE_ID, VALUE_ID + 1, VALUE_ID + 1,
						VALUE_ID + 1, VALUE_ID + 1, VALUE_ID + 1), actual,
						"PlanRows through LmdbNativeKernelBindings must expand each weighted solution exactly");
				assertEquals(1, plainPlan.opens, "the bound row plan opens one physical producer");
				assertEquals(3, plainPlan.nextCalls, "two physical rows and exhaustion stay bounded");
				assertEquals(1, plainPlan.closes, "normal PlanRows exhaustion closes the owned producer");
				assertEquals(plainBaseline, plainLedger.usedBytes(), "row-plan completion releases query ownership");
			} finally {
				rowKernel.close();
				rowContext.plans[0].close();
				plainRow.memoryScope.close();
				GeneratedBorrowedFtreeContractTest.remove(rowDirectory);
			}

			RowState weightedRow = row(new NativeCancellationToken());
			LmdbQueryMemoryManager.QueryLedger weightedLedger = weightedRow.memoryScope.ledger(manager);
			long weightedBaseline = weightedLedger.usedBytes();
			long largeWeight = 1L << 40;
			WeightedPlan weightedPlan = new WeightedPlan(weightedRow, VALUE_SLOT, VALUE_ID, largeWeight, null);
			LmdbNativeKernelIr.Kernel countShape = new LmdbNativeKernelIr.Kernel(1,
					List.of(new LmdbNativeKernelIr.PlanRows(0, new int[] { 0 })),
					new LmdbNativeKernelIr.Aggregate(new int[0],
							new LmdbNativeKernelIr.AggregateOutput[] {
									LmdbNativeKernelIr.AggregateOutput.countStar() },
							null, LmdbNativeKernelIr.OutputMods.none()));
			Path countDirectory = Files.createTempDirectory("bound-plan-count-");
			KernelContext countContext = boundPlanContext(weightedRow, weightedPlan);
			JaninoKernel countKernel = GeneratedBorrowedFtreeContractTest.compile(countShape.className(),
					LmdbNativeKernelEmitter.emit(countShape), countDirectory);
			try {
				countKernel.bind(countContext);
				long[] result = new long[1];
				assertEquals(1, countKernel.fill(result, 1), "COUNT(*) emits one scalar result");
				assertEquals(largeWeight, result[0], "the real bound weighted fill preserves a large exact factor");
				assertEquals(0, countKernel.fill(result, 1), "the aggregate result is complete");
				assertEquals(1, weightedPlan.opens, "weighted PlanRows opens one physical producer");
				assertEquals(2, weightedPlan.nextCalls,
						"one large factor is read in constant physical pulls, including exhaustion");
				assertEquals(1, weightedPlan.closes, "weighted completion closes the owned producer");
				countKernel.close();
				countContext.plans[0].close();
				assertEquals(weightedBaseline, weightedLedger.usedBytes(),
						"closing the weighted kernel and plan releases query ownership");
			} finally {
				countKernel.close();
				countContext.plans[0].close();
				weightedRow.memoryScope.close();
				GeneratedBorrowedFtreeContractTest.remove(countDirectory);
			}

			RowState mixedRow = row(new NativeCancellationToken());
			LmdbQueryMemoryManager.QueryLedger mixedLedger = mixedRow.memoryScope.ledger(manager);
			long mixedBaseline = mixedLedger.usedBytes();
			WeightedPlan mixedPlan = new WeightedPlan(mixedRow, VALUE_SLOT,
					new long[] { VALUE_ID, VALUE_ID + 1 }, new long[] { 3L, 5L }, null);
			KernelContext mixedContext = boundPlanContext(mixedRow, mixedPlan);
			KernelPlan.Cursor mixedCursor = mixedContext.plans[0].open();
			try {
				long[] first = new long[3];
				assertEquals(1, mixedCursor.fill(first, first.length),
						"ordinary fill expands only the first row of a partial window");
				assertEquals(VALUE_ID, first[0]);
				long[] remainder = new long[2];
				long[] weights = new long[2];
				List<Long> mixedValues = new ArrayList<>();
				List<Long> mixedWeights = new ArrayList<>();
				List<Long> mixedBag = new ArrayList<>();
				int weightedCount;
				while ((weightedCount = mixedCursor.fillWeighted(remainder, weights, remainder.length)) > 0) {
					for (int i = 0; i < weightedCount; i++) {
						mixedValues.add(remainder[i]);
						mixedWeights.add(weights[i]);
						for (int repeat = 0; repeat < weights[i]; repeat++) {
							mixedBag.add(remainder[i]);
						}
					}
				}
				assertEquals(List.of(VALUE_ID, VALUE_ID + 1), mixedValues,
						"successive weighted windows preserve the remaining physical rows");
				assertEquals(List.of(2L, 5L), mixedWeights,
						"successive weighted windows preserve each remaining factor");
				assertEquals(List.of(VALUE_ID, VALUE_ID, VALUE_ID + 1, VALUE_ID + 1, VALUE_ID + 1,
						VALUE_ID + 1, VALUE_ID + 1), mixedBag,
						"partial ordinary then weighted fills preserve the exact remaining bag");
				assertEquals(3, mixedPlan.nextCalls, "mixed fills advance two rows and then observe exhaustion");
				assertEquals(1, mixedPlan.closes, "mixed-window exhaustion closes the physical producer");
				assertEquals(mixedBaseline, mixedLedger.usedBytes(), "mixed fills release query ownership");
			} finally {
				mixedCursor.close();
				mixedContext.plans[0].close();
				mixedRow.memoryScope.close();
			}

			NativeCancellationToken cancellation = new NativeCancellationToken();
			RowState cancelledRow = row(cancellation);
			LmdbQueryMemoryManager.QueryLedger cancelledLedger = cancelledRow.memoryScope.ledger(manager);
			long cancelledBaseline = cancelledLedger.usedBytes();
			WeightedPlan cancelledPlan = new WeightedPlan(cancelledRow, VALUE_SLOT, VALUE_ID, 9L, null);
			KernelContext cancelledContext = boundPlanContext(cancelledRow, cancelledPlan);
			KernelPlan.Cursor cancelledCursor = cancelledContext.plans[0].open();
			try {
				assertEquals(1, cancelledCursor.fill(new long[2], 2),
						"the first logical row is visible before cancellation");
				cancellation.requestCancellation();
				assertEquals(0, cancelledCursor.fillWeighted(new long[2], new long[2], 2));
				assertEquals(1, cancelledPlan.closes, "cancellation closes the bound physical producer");
				assertEquals(1, cancelledPlan.nextCalls, "cancellation prevents another physical pull");
				assertEquals(cancelledBaseline, cancelledLedger.usedBytes(),
						"cancellation releases query ownership");
			} finally {
				cancelledCursor.close();
				cancelledContext.plans[0].close();
				cancelledRow.memoryScope.close();
			}
		} finally {
			LmdbNativeHashJoin.queryMemoryOverride = previous;
		}
	}

	@Test
	void leftCancellationKeepsItsCloseFailureAndReleasesTheMemoLedger() throws IOException {
		LmdbQueryMemoryManager previous = LmdbNativeHashJoin.queryMemoryOverride;
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(65_536L, 65_536L);
		LmdbNativeHashJoin.queryMemoryOverride = manager;
		RowState row = row(new NativeCancellationToken());
		LmdbQueryMemoryManager.QueryLedger ledger = row.memoryScope.ledger(manager);
		RuntimeException closeFailure = new IllegalStateException("left cursor close failed");
		SlotPlan left = new FailingPlan(1L << KEY_SLOT, KernelQueryCancelledException.INSTANCE, closeFailure);
		SlotPlan right = new WeightedPlan(row, VALUE_SLOT, VALUE_ID, 1L, null);
		RowCursor cursor = new NativeAliasJoinMemoPlan(new JoinPlan(left, right)).open(row);

		try {
			Throwable failure = nextFailure(cursor);
			assertNotNull(failure, "left cursor cancellation must escape");
			assertTrue(contains(failure, closeFailure),
					"left close failure must remain reachable beside query cancellation");
		} finally {
			try {
				cursor.close();
				assertEquals(0L, ledger.usedBytes(), "left cancellation must release memo ledger reservations");
			} finally {
				row.memoryScope.close();
				LmdbNativeHashJoin.queryMemoryOverride = previous;
			}
		}
	}

	@Test
	void directJoinCursorClosesOwnedResourcesAfterRhsCloseFailure() throws IOException {
		LmdbQueryMemoryManager previous = LmdbNativeHashJoin.queryMemoryOverride;
		LmdbQueryMemoryManager previousAdaptive = LmdbAdaptiveLongArray.queryMemoryOverride;
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(65_536L, 65_536L);
		LmdbNativeHashJoin.queryMemoryOverride = manager;
		LmdbAdaptiveLongArray.queryMemoryOverride = manager;
		RowState row = row(new NativeCancellationToken());
		LmdbQueryMemoryManager.QueryLedger ledger = row.memoryScope.ledger(manager);
		long baseline = ledger.usedBytes();
		RuntimeException rightCloseFailure = new IllegalStateException("normal right cursor close failed");
		RuntimeException leftCloseFailure = new IllegalArgumentException("owned left cursor close failed");
		WeightedPlan left = new WeightedPlan(row, KEY_SLOT, KEY_ID, 1L, leftCloseFailure);
		RowCursor leftCursor = left.open(row);
		int[] rightCloseCalls = { 0 };
		NativeBooleanFilter closeFailingFilter = new NativeBooleanFilter() {
			@Override
			public boolean accept(RowState executionRow) {
				return true;
			}

			@Override
			public void close() {
				rightCloseCalls[0]++;
				throw rightCloseFailure;
			}
		};
		ValuesPlan values = new ValuesPlan(
				new ValuesRow[] { new ValuesRow(new int[] { VALUE_SLOT }, new long[] { VALUE_ID }) });
		FilterPlan right = new FilterPlan(values, closeFailingFilter, 0L);
		JoinCursor join = new JoinCursor(leftCursor, right, row, left.producedMask());

		try {
			assertTrue(join.next(), "the normally opened RHS emits its first row");
			assertEquals(VALUE_ID, row.slots[VALUE_SLOT], "the RHS row is bound before close");
			assertTrue(ledger.usedBytes() > baseline,
					"the completed replay row reserves query-ledger storage before cleanup");

			Throwable failure = null;
			try {
				join.close();
			} catch (Throwable stopped) {
				failure = stopped;
			}
			Throwable observedFailure = failure;
			assertAll("JoinCursor closes every owned resource even when RHS close fails",
					() -> assertSame(rightCloseFailure, observedFailure, "RHS close remains primary"),
					() -> assertEquals(1, rightCloseCalls[0], "RHS owner closes once"),
					() -> assertEquals(1, left.closes, "left owner closes once after the RHS failure"),
					() -> assertTrue(contains(observedFailure, leftCloseFailure),
							"later owned-close failures remain reachable"),
					() -> assertEquals(baseline, ledger.usedBytes(), "replay storage is released despite RHS failure"));
		} finally {
			if (rightCloseCalls[0] == 0) {
				try {
					join.close();
				} catch (Throwable ignored) {
				}
			}
			if (left.closes == 0) {
				try {
					leftCursor.close();
				} catch (Throwable ignored) {
				}
			}
			try {
				row.memoryScope.close();
			} finally {
				LmdbNativeHashJoin.queryMemoryOverride = previous;
				LmdbAdaptiveLongArray.queryMemoryOverride = previousAdaptive;
			}
		}
	}

	@Test
	void deadlineAndControlFailuresRetainCloseErrorsForJoinAndLateralCursors() throws IOException {
		assertAll("suppression-disabled controls must not hide real owner cleanup failures",
				this::directJoinProbeDeadlineCloseFailureKeepsLaterOwnerFailure,
				() -> assertCursorCloseFailurePrimaryAfterNextFailure("JoinCursor cancellation", false,
						KernelQueryCancelledException.INSTANCE),
				() -> assertCursorCloseFailurePrimaryAfterNextFailure("JoinCursor probe deadline", false,
						LmdbNativeProbeDeadlineExceeded.INSTANCE),
				() -> assertCursorCloseFailurePrimaryAfterNextFailure("LateralCursor cancellation", true,
						KernelQueryCancelledException.INSTANCE),
				() -> assertCursorCloseFailurePrimaryAfterNextFailure("LateralCursor probe deadline", true,
						LmdbNativeProbeDeadlineExceeded.INSTANCE));
	}

	private void directJoinProbeDeadlineCloseFailureKeepsLaterOwnerFailure() throws IOException {
		LmdbQueryMemoryManager previous = LmdbNativeHashJoin.queryMemoryOverride;
		LmdbQueryMemoryManager previousAdaptive = LmdbAdaptiveLongArray.queryMemoryOverride;
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(65_536L, 65_536L);
		LmdbNativeHashJoin.queryMemoryOverride = manager;
		LmdbAdaptiveLongArray.queryMemoryOverride = manager;
		RowState row = row(new NativeCancellationToken());
		LmdbQueryMemoryManager.QueryLedger ledger = row.memoryScope.ledger(manager);
		long baseline = ledger.usedBytes();
		WeightedPlan left = new WeightedPlan(row, KEY_SLOT, KEY_ID, 1L,
				new IllegalArgumentException("left owner cleanup sentinel"));
		int[] rightCloseCalls = { 0 };
		NativeBooleanFilter deadlineOnClose = new NativeBooleanFilter() {
			@Override
			public boolean accept(RowState executionRow) {
				return true;
			}

			@Override
			public void close() {
				rightCloseCalls[0]++;
				throw LmdbNativeProbeDeadlineExceeded.INSTANCE;
			}
		};
		ValuesPlan values = new ValuesPlan(
				new ValuesRow[] { new ValuesRow(new int[] { VALUE_SLOT }, new long[] { VALUE_ID }) });
		FilterPlan right = new FilterPlan(values, deadlineOnClose, 0L);
		RowCursor leftCursor = left.open(row);
		JoinCursor join = new JoinCursor(leftCursor, right, row, left.producedMask());

		try {
			assertTrue(join.next(), "the normally opened RHS emits one row before cleanup");
			Throwable observed = null;
			try {
				join.close();
			} catch (Throwable failure) {
				observed = failure;
			}
			Throwable actual = observed;
			RuntimeException leftCloseFailure = left.closeFailure;
			assertAll("deadline from the RHS close must not discard the later real left-close failure",
					() -> assertSame(leftCloseFailure, actual,
							"the real left-close failure must become primary"),
					() -> assertTrue(actual != null && contains(actual, LmdbNativeProbeDeadlineExceeded.INSTANCE),
							"the earlier deadline remains reachable from the cleanup failure"),
					() -> assertEquals(1, rightCloseCalls[0], "the RHS owner closes exactly once"),
					() -> assertEquals(1, left.closes, "the left owner is still attempted after RHS deadline"),
					() -> assertEquals(baseline, ledger.usedBytes(), "all replay reservations are released"));
		} finally {
			if (left.closes == 0 || rightCloseCalls[0] == 0) {
				try {
					join.close();
				} catch (Throwable ignored) {
				}
			}
			if (left.closes == 0) {
				try {
					leftCursor.close();
				} catch (Throwable ignored) {
				}
			}
			try {
				row.memoryScope.close();
			} finally {
				LmdbNativeHashJoin.queryMemoryOverride = previous;
				LmdbAdaptiveLongArray.queryMemoryOverride = previousAdaptive;
			}
		}
	}

	private void assertCursorCloseFailurePrimaryAfterNextFailure(String label, boolean lateral,
			RuntimeException evaluationFailure) throws IOException {
		RowState row = row(new NativeCancellationToken());
		RuntimeException closeFailure = new IllegalStateException(label + " owner cleanup sentinel");
		FailingPlan left = new FailingPlan(1L << KEY_SLOT, evaluationFailure, closeFailure);
		RowCursor leftCursor = left.open(row);
		ValuesPlan right = new ValuesPlan(
				new ValuesRow[] { new ValuesRow(new int[] { VALUE_SLOT }, new long[] { VALUE_ID }) });
		FactorizedRowCursor cursor = lateral
				? new LateralCursor(leftCursor, right, left.producedMask(), row)
				: new JoinCursor(leftCursor, right, row, left.producedMask());
		Throwable observed = null;
		try (cursor) {
			cursor.next();
		} catch (Throwable failure) {
			observed = failure;
		} finally {
			row.memoryScope.close();
		}
		Throwable actual = observed;
		assertAll(label + " cleanup failure handling",
				() -> assertSame(closeFailure, actual, "the real close failure remains primary"),
				() -> assertTrue(actual != null && contains(actual, evaluationFailure),
						"the original control signal remains reachable"),
				() -> assertEquals(1, left.opens, "the throwing left cursor opens once"),
				() -> assertEquals(1, left.nextCalls, "the left cursor fails on its first pull"),
				() -> assertEquals(1, left.closes, "the left owner closes once after next fails"));
	}

	@Test
	void rightCaptureCancellationKeepsItsCloseFailureAndReleasesTheMemoLedger() throws IOException {
		LmdbQueryMemoryManager previous = LmdbNativeHashJoin.queryMemoryOverride;
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(65_536L, 65_536L);
		LmdbNativeHashJoin.queryMemoryOverride = manager;
		RowState row = row(new NativeCancellationToken());
		LmdbQueryMemoryManager.QueryLedger ledger = row.memoryScope.ledger(manager);
		RuntimeException closeFailure = new IllegalStateException("right cursor close failed");
		SlotPlan left = new WeightedPlan(row, KEY_SLOT, KEY_ID, 1L, null);
		SlotPlan right = new FailingPlan(1L << VALUE_SLOT, KernelQueryCancelledException.INSTANCE, closeFailure);
		RowCursor cursor = new NativeAliasJoinMemoPlan(new JoinPlan(left, right)).open(row);

		try {
			Throwable failure = nextFailure(cursor);
			assertNotNull(failure, "right capture cancellation must escape");
			assertTrue(contains(failure, closeFailure),
					"right capture close failure must remain reachable beside query cancellation");
		} finally {
			try {
				cursor.close();
				assertEquals(0L, ledger.usedBytes(),
						"right capture cancellation must release memo ledger reservations");
			} finally {
				row.memoryScope.close();
				LmdbNativeHashJoin.queryMemoryOverride = previous;
			}
		}
	}

