	@Test
	void boundCursorProbeDeadlineKeepsCloseFailureAndReleasesMemoLedger() throws IOException {
		LmdbQueryMemoryManager previous = LmdbNativeHashJoin.queryMemoryOverride;
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(1L << 20, 1L << 20);
		LmdbNativeHashJoin.queryMemoryOverride = manager;
		RowState row = row(new NativeCancellationToken());
		LmdbQueryMemoryManager.QueryLedger ledger = row.memoryScope.ledger(manager);
		long baseline = ledger.usedBytes();
		RuntimeException closeFailure = new IllegalStateException("weighted right cursor close failed");
		SlotPlan left = new WeightedPlan(row, KEY_SLOT, KEY_ID, 1L, null);
		WeightedPlan right = new WeightedPlan(row, VALUE_SLOT, VALUE_ID, 2_048L, closeFailure);
		SlotPlan memoizedJoin = new NativeAliasJoinMemoPlan(new JoinPlan(left, right));
		KernelContext context = boundPlanContext(row, memoizedJoin);
		KernelPlan.Cursor boundCursor = context.plans[0].open();
		LmdbNativeProbeDeadline deadline = LmdbNativeProbeDeadline.trippableOnly();

		try (LmdbNativeProbeDeadline.Scope ignored = LmdbNativeProbeDeadline.enter(deadline)) {
			long[] partialWindow = new long[1];
			assertEquals(1, boundCursor.fill(partialWindow, 1),
					"the first plain window must emit before the deadline expires");
			assertEquals(VALUE_ID, partialWindow[0], "the first RHS value is observed before expiration");
			assertTrue(ledger.usedBytes() > baseline,
					"the real memo fragment must own query-ledger memory before the forced close");
			deadline.trip();

			Throwable failure = null;
			int fillAttempts = 0;
			for (int i = 0; i < 1_024; i++) {
				fillAttempts++;
				try {
					boundCursor.fill(new long[1], 1);
				} catch (Throwable stopped) {
					failure = stopped;
					break;
				}
			}
			assertSame(closeFailure, failure,
					"the real RHS close failure must become primary when the BoundCursor poll closes its owner");
			assertEquals(1_023, fillAttempts,
					"the only poll firing is the outer BoundCursor poll after the partial first window");
			assertEquals(1, right.nextCalls,
					"the memoized RHS cursor remains at one physical weighted emission during outer draining");
			assertTrue(contains(failure, LmdbNativeProbeDeadlineExceeded.INSTANCE),
					"the original suppression-disabled probe signal remains available as cleanup evidence");
			assertEquals(baseline, ledger.usedBytes(), "the failed BoundCursor fill must release memo reservations");
		} finally {
			try {
				boundCursor.close();
				context.plans[0].close();
				assertEquals(baseline, ledger.usedBytes(), "closing the bound owner leaves no memo reservations");
			} finally {
				row.memoryScope.close();
				LmdbNativeHashJoin.queryMemoryOverride = previous;
			}
		}
	}

	@Test
	void boundCursorCancellationKeepsCloseFailureAndReleasesQueryLedger() throws IOException {
		LmdbQueryMemoryManager previous = LmdbNativeHashJoin.queryMemoryOverride;
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(1L << 20, 1L << 20);
		LmdbNativeHashJoin.queryMemoryOverride = manager;
		NativeCancellationToken cancellation = new NativeCancellationToken();
		RowState row = row(cancellation);
		LmdbQueryMemoryManager.QueryLedger ledger = row.memoryScope.ledger(manager);
		long baseline = ledger.usedBytes();
		RuntimeException closeFailure = new IllegalStateException("cancelled plan close failed");
		int[] closes = { 0 };
		SlotPlan cancelingPlan = new SlotPlan() {
			@Override
			public RowCursor open(RowState executionRow) {
				KernelRuntime.AggregateMemory memory = KernelRuntime.AggregateMemory
						.forLedger(executionRow.memoryScope.ledger(manager));
				assertTrue(memory.tryReserve(64L), "the controlled cursor reserves query-ledger memory");
				return new RowCursor() {
					private boolean closed;

					@Override
					public boolean next() {
						executionRow.cancellation.requestCancellation();
						executionRow.cancellation.check();
						return false;
					}

					@Override
					public void close() {
						if (!closed) {
							closed = true;
							closes[0]++;
							memory.close();
							throw closeFailure;
						}
					}
				};
			}

			@Override
			public long producedMask() {
				return 1L << VALUE_SLOT;
			}
		};
		KernelContext context = boundPlanContext(row, cancelingPlan);
		KernelPlan.Cursor boundCursor = context.plans[0].open();

		try {
			Throwable failure = null;
			try {
				boundCursor.fill(new long[1], 1);
			} catch (Throwable stopped) {
				failure = stopped;
			}
			assertSame(closeFailure, failure, "the real close failure must remain primary over query cancellation");
			assertEquals(1, failure.getSuppressed().length,
					"the real cleanup failure retains its query-cancellation occurrence once");
			assertTrue(failure.getSuppressed()[0] instanceof KernelQueryCancelledException,
					"the retained cleanup evidence is the query-cancellation occurrence");
			KernelQueryCancelledException retained = (KernelQueryCancelledException) failure.getSuppressed()[0];
			assertNotSame(KernelQueryCancelledException.INSTANCE, retained);
			assertSame(row.cancellation, retained.origin());
			assertTrue(retained.observedBy(row.cancellation));
			assertEquals(1, closes[0], "BoundCursor closes its owned plan cursor exactly once");
			assertEquals(baseline, ledger.usedBytes(), "cancellation cleanup releases query-ledger memory");
		} finally {
			try {
				boundCursor.close();
				context.plans[0].close();
			} finally {
				row.memoryScope.close();
				LmdbNativeHashJoin.queryMemoryOverride = previous;
			}
		}
	}

	private static RowState row(NativeCancellationToken cancellation) {
		NativeSlotLayout layout = new NativeSlotLayout(Map.of("key", KEY_SLOT, "value", VALUE_SLOT), null);
		layout.freeze(List.of("key", "value"));
		RowState row = new RowState(null, layout, EmptyBindingSet.getInstance(), (TupleExpr) null, cancellation);
		assertTrue(LmdbNativeAggregateCompiler.initializeRow(row, row.base, row.source, row.layout));
		return row;
	}

