	private static Map<String, Integer> queryBag(SailRepository repository, String queryText) {
		return queryBag(repository, queryText, Map.of());
	}

	private static Map<String, Integer> queryBag(SailRepository repository, String queryText,
			Map<String, Value> bindings) {
		try (var connection = repository.getConnection()) {
			TupleQuery query = connection.prepareTupleQuery(queryText);
			((SailQuery) query).setLmdbResultCacheRequested(false);
			bindings.forEach(query::setBinding);
			Map<String, Integer> bag = new HashMap<>();
			try (var rows = query.evaluate()) {
				while (rows.hasNext()) {
					BindingSet row = rows.next();
					String result = row.getValue("source").stringValue() + "|" + row.getValue("value").stringValue();
					bag.merge(result, 1, Integer::sum);
				}
			}
			return bag;
		}
	}

	private static QueryMeasurement runNativeQuery(SailRepository repository, String queryText,
			LmdbQueryMemoryManager manager) {
		return runNativeQuery(repository, queryText, manager, Map.of());
	}

	private static QueryMeasurement runNativeQuery(SailRepository repository, String queryText,
			LmdbQueryMemoryManager manager, Map<String, Value> bindings) {
		LmdbQueryMemoryManager previous = LmdbNativeHashJoin.queryMemoryOverride;
		LmdbNativeHashJoin.queryMemoryOverride = manager;
		try (var connection = repository.getConnection()) {
			SailTupleQuery query = (SailTupleQuery) connection.prepareTupleQuery(queryText);
			query.setForcedLmdbExecutionStrategy("nestedLoop");
			query.setLmdbResultCacheRequested(false);
			bindings.forEach(query::setBinding);
			Map<String, Integer> bag = new HashMap<>();
			try (var rows = query.evaluate()) {
				while (rows.hasNext()) {
					BindingSet row = rows.next();
					String result = row.getValue("source").stringValue() + "|" + row.getValue("value").stringValue();
					bag.merge(result, 1, Integer::sum);
				}
			}
			String telemetry = query.explain(Explanation.Level.Telemetry).toString();
			return new QueryMeasurement(bag, telemetry, scannedRows(telemetry), manager.peakUsedBytes(),
					manager.usedBytes());
		} finally {
			LmdbNativeHashJoin.queryMemoryOverride = previous;
		}
	}

	private static long facetSourceOpens(String telemetry) {
		int access = telemetry.indexOf("adjacencyAccess:");
		int attempts = telemetry.indexOf("attempts:", access);
		int measurements = telemetry.indexOf("measurements:", attempts);
		if (access < 0 || attempts < 0 || measurements < 0) {
			return -1L;
		}
		String attemptText = telemetry.substring(attempts, measurements);
		for (String attempt : attemptText.split("(?m)^\\s+\\d+:\\s*$")) {
			if (attempt.contains("source: LMDB") && attempt.contains("outcome: SELECTED")
					&& attempt.contains("where: Pattern(s=?focus#") && attempt.contains("indexName=posc")) {
				Matcher matcher = OPEN_COUNT.matcher(attempt);
				if (matcher.find()) {
					return Long.parseLong(matcher.group(1));
				}
			}
		}
		return -1L;
	}

	private static long scannedRows(String telemetry) {
		int queryPlanEnd = telemetry.indexOf("\n\nQuery explanation");
		String physicalPlan = queryPlanEnd < 0 ? telemetry : telemetry.substring(0, queryPlanEnd);
		Matcher matcher = SCANNED_ROWS.matcher(physicalPlan);
		long scanned = 0L;
		while (matcher.find()) {
			scanned = Math.addExact(scanned, Long.parseLong(matcher.group(1)));
		}
		return scanned;
	}

